// Rapport Markdown hebdo — brancher un nœud Email (Resend) ou Telegram
// à la suite quand les clés seront disponibles.
const s = $input.first().json;
const regions = (s.by_region ?? []).map(r => `- ${r.region ?? 'hors périmètre'} : ${r.count}`).join('
');
const sources = (s.by_source ?? []).map(r => `- ${r.source} : ${r.count}`).join('
');
const rapport = `# TRIPTIC — Base de lieux (${new Date().toLocaleDateString('fr-FR')})

` +
  `**Total : ${s.total} lieux** · en modération : ${s.pending}

` +
  `## Par région
${regions}

## Par source
${sources}
`;
return [{ json: { rapport, total: s.total, pending: s.pending } }];
